1	//! `MessageTranslator` — Anthropic SSE events → `ModelEvent` stream.
2	
3	use std::collections::HashMap;
4	
5	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
6	
7	use crate::error::map_error_type;
8	use crate::sse::{
9	    AnthropicEvent, ContentBlockDelta, ContentBlockHead, MessageDeltaUsage, MessageStartUsage,
10	};
11	use crate::translate::response_format::SYNTHESIZED_TOOL_NAME;
12	
13	#[derive(Debug)]
14	enum BlockState {
15	    Text,
16	    Thinking,
17	    ToolUse {
18	        call_id: String,
19	        name: String,
20	        name_emitted: bool,
21	    },
22	}
23	
24	/// State machine for one streaming response.
25	///
26	/// `synthesizing_output: true` means a `ResponseFormat::JsonSchema`/`JsonObject`
27	/// request was sent. When the synthesized tool's content block starts, its
28	/// `input_json_delta` events are remapped to `TokenDelta`s and the
29	/// `stop_reason: "tool_use"` is rewritten to `Stop` if it was the only tool fired.
30	pub(crate) struct MessageTranslator {
31	    blocks: HashMap<u32, BlockState>,
32	    last_input_tokens: u32,
33	    last_cached_input_tokens: Option<u32>,
34	    stop_reason: Option<String>,
35	    synthesizing_output: bool,
36	    synthesized_tool_index: Option<u32>,
37	    other_tool_fired: bool,
38	}
39	
40	impl MessageTranslator {
41	    pub(crate) fn new(synthesizing_output: bool) -> Self {
42	        Self {
43	            blocks: HashMap::new(),
44	            last_input_tokens: 0,
45	            last_cached_input_tokens: None,
46	            stop_reason: None,
47	            synthesizing_output,
48	            synthesized_tool_index: None,
49	            other_tool_fired: false,
50	        }
51	    }
52	
53	    /// Consume one event. Returns the emitted ModelEvents (most calls
54	    /// emit zero or one; `message_delta` carrying both stop_reason and
55	    /// usage emits one Usage followed by Finish on `message_stop`).
56	    pub(crate) fn consume(
57	        &mut self,
58	        event: AnthropicEvent,
59	    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
60	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
61	        match event {
62	            AnthropicEvent::MessageStart { message } => {
63	                let MessageStartUsage {
64	                    input_tokens,
65	                    cache_read_input_tokens,
66	                    ..
67	                } = message.usage;
68	                self.last_input_tokens = input_tokens;
69	                self.last_cached_input_tokens = cache_read_input_tokens;
70	                out.push(Ok(ModelEvent::Usage {
71	                    input_tokens,
72	                    output_tokens: 0,
73	                    cached_input_tokens: cache_read_input_tokens,
74	                    reasoning_tokens: None,
75	                }));
76	            }
77	            AnthropicEvent::ContentBlockStart {
78	                index,
79	                content_block,
80	            } => match content_block {
81	                ContentBlockHead::Text => {
82	                    self.blocks.insert(index, BlockState::Text);
83	                }
84	                ContentBlockHead::Thinking => {
85	                    self.blocks.insert(index, BlockState::Thinking);
86	                }
87	                ContentBlockHead::ToolUse { id, name, .. } => {
88	                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
89	                        self.synthesized_tool_index = Some(index);
90	                    } else {
91	                        self.other_tool_fired = true;
92	                    }
93	                    self.blocks.insert(
94	                        index,
95	                        BlockState::ToolUse {
96	                            call_id: id,
97	                            name,
98	                            name_emitted: false,
99	                        },
100	                    );
101	                }
102	            },
103	            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
104	                ContentBlockDelta::TextDelta { text } => {
105	                    out.push(Ok(ModelEvent::TokenDelta { text }));
106	                }
107	                ContentBlockDelta::ThinkingDelta { thinking } => {
108	                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
109	                }
110	                ContentBlockDelta::SignatureDelta { .. } => {
111	                    tracing::debug!(
112	                        target: "paigasus::anthropic::stream",
113	                        "signature_delta dropped (round-trip not yet supported)",
114	                    );
115	                }
116	                ContentBlockDelta::InputJsonDelta { partial_json } => {
117	                    let is_synth = Some(index) == self.synthesized_tool_index;
118	                    if is_synth {
119	                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
120	                    } else if let Some(BlockState::ToolUse {
121	                        call_id,
122	                        name,
123	                        name_emitted,
124	                    }) = self.blocks.get_mut(&index)
125	                    {
126	                        let (emit_name, call_id_out) = if *name_emitted {
127	                            (None, call_id.clone())
128	                        } else {
129	                            *name_emitted = true;
130	                            (Some(name.clone()), call_id.clone())
131	                        };
132	                        out.push(Ok(ModelEvent::ToolCallDelta {
133	                            call_id: call_id_out,
134	                            name: emit_name,
135	                            args_delta: partial_json,
136	                        }));
137	                    } else {
138	                        // Protocol violation: input_json_delta only ever
139	                        // applies to a tool_use content block. Surface it
140	                        // rather than silently dropping (which would mask
141	                        // a malformed upstream stream).
142	                        return Err(ModelError::Transport(format!(
143	                            "anthropic stream: input_json_delta at index {index} \
144	                             has no preceding tool_use content_block_start"
145	                        )));
146	                    }
147	                }
148	            },
149	            AnthropicEvent::ContentBlockStop { .. } => {
150	                tracing::debug!(target: "paigasus::anthropic::stream", "content_block_stop");
151	            }
152	            AnthropicEvent::MessageDelta { delta, usage } => {
153	                if let Some(MessageDeltaUsage { output_tokens }) = usage {
154	                    out.push(Ok(ModelEvent::Usage {
155	                        input_tokens: self.last_input_tokens,
156	                        output_tokens,
157	                        cached_input_tokens: self.last_cached_input_tokens,
158	                        reasoning_tokens: None,
159	                    }));
160	                }
161	                if let Some(reason) = delta.stop_reason {
162	                    self.stop_reason = Some(reason);
163	                }
164	            }
165	            AnthropicEvent::MessageStop => {
166	                if let Some(reason) = self.stop_reason.take() {
167	                    out.push(self.finish_or_error(&reason));
168	                }
169	            }
170	            AnthropicEvent::Ping => {}
171	            AnthropicEvent::Error { error } => {
172	                return Err(map_error_type(None, &error.ty, &error.message, None));
173	            }
174	        }
175	        Ok(out)
176	    }
177	
178	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
179	        match reason {
180	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
181	                reason: FinishReason::Stop,
182	            }),
183	            "max_tokens" => Ok(ModelEvent::Finish {
184	                reason: FinishReason::Length,
185	            }),
186	            "tool_use" => {
187	                if self.synthesizing_output && !self.other_tool_fired {
188	                    Ok(ModelEvent::Finish {
189	                        reason: FinishReason::Stop,
190	                    })
191	                } else if self.synthesizing_output && self.other_tool_fired {
192	                    Err(ModelError::Other(anyhow::anyhow!(
193	                        "structured output: model fired both a real tool and the synthesized output tool"
194	                    )))
195	                } else {
196	                    Ok(ModelEvent::Finish {
197	                        reason: FinishReason::ToolCalls,
198	                    })
199	                }
200	            }
201	            "refusal" => Err(ModelError::Refused {
202	                reason: "model refused".to_owned(),
203	            }),
204	            other => Ok(ModelEvent::Finish {
205	                reason: FinishReason::Other(other.to_owned()),
206	            }),
207	        }
208	    }
209	}
