1	//! Streaming SSE fixture tests for the Anthropic provider.
2	//!
3	//! Note: wiremock serves the full fixture body in a single chunk; these
4	//! tests prove byte-level correctness, not resilience to slow chunk delivery.
5	
6	use futures_util::StreamExt;
7	use paigasus_helikon_core::{
8	    CancellationToken, ContentPart, FinishReason, Item, Model, ModelError, ModelEvent, ModelRequest,
9	};
10	use paigasus_helikon_providers_anthropic::AnthropicModel;
11	use wiremock::matchers::{method, path};
12	use wiremock::{Mock, MockServer, Respond, ResponseTemplate};
13	
14	fn user(s: &str) -> Item {
15	    Item::UserMessage {
16	        content: vec![ContentPart::Text { text: s.to_owned() }],
17	    }
18	}
19	
20	fn req_with(messages: Vec<Item>) -> ModelRequest {
21	    let mut r = ModelRequest::new();
22	    r.messages = messages;
23	    r
24	}
25	
26	async fn run_stream(
27	    server: &MockServer,
28	    fixture: &'static str,
29	) -> Vec<Result<ModelEvent, ModelError>> {
30	    Mock::given(method("POST"))
31	        .and(path("/v1/messages"))
32	        .respond_with(
33	            ResponseTemplate::new(200)
34	                .insert_header("content-type", "text/event-stream")
35	                .set_body_raw(fixture, "text/event-stream"),
36	        )
37	        .mount(server)
38	        .await;
39	
40	    let model = AnthropicModel::messages("claude-sonnet-4-6")
41	        .api_key("sk-test")
42	        .base_url(server.uri())
43	        .build()
44	        .unwrap();
45	    let mut s = model
46	        .invoke(req_with(vec![user("hi")]), CancellationToken::new())
47	        .await
48	        .unwrap();
49	    let mut out = Vec::new();
50	    while let Some(ev) = s.next().await {
51	        out.push(ev);
52	    }
53	    out
54	}
55	
56	#[tokio::test]
57	async fn text_only_stream_emits_usage_token_deltas_usage_finish() {
58	    let server = MockServer::start().await;
59	    let fixture = include_str!("fixtures/text_only.txt");
60	    let events = run_stream(&server, fixture).await;
61	    let oks: Vec<_> = events.into_iter().map(|r| r.unwrap()).collect();
62	
63	    // First: Usage from message_start.
64	    assert!(matches!(
65	        oks[0],
66	        ModelEvent::Usage {
67	            input_tokens: 12,
68	            output_tokens: 0,
69	            ..
70	        }
71	    ));
72	    // Then two TokenDelta events.
73	    assert!(matches!(&oks[1], ModelEvent::TokenDelta { text } if text == "Hello"));
74	    assert!(matches!(&oks[2], ModelEvent::TokenDelta { text } if text == " world"));
75	    // Final Usage from message_delta then Finish::Stop.
76	    assert!(matches!(
77	        oks[3],
78	        ModelEvent::Usage {
79	            output_tokens: 5,
80	            ..
81	        }
82	    ));
83	    assert!(matches!(&oks[4], ModelEvent::Finish { reason } if *reason == FinishReason::Stop));
84	}
85	
86	#[tokio::test]
87	async fn parallel_tool_use_stream_emits_two_tool_call_deltas() {
88	    let server = MockServer::start().await;
89	    let fixture = include_str!("fixtures/parallel_tool_use.txt");
90	    let events = run_stream(&server, fixture).await;
91	    let oks: Vec<_> = events.into_iter().map(|r| r.unwrap()).collect();
92	
93	    let tc: Vec<&ModelEvent> = oks
94	        .iter()
95	        .filter(|e| matches!(e, ModelEvent::ToolCallDelta { .. }))
96	        .collect();
